runners.capacity:
import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {installDevelopmentProcessLifecycle} from '../../scripts/development-process-lifecycle.mjs';
import {startSsrLoadProcess} from '../../framework-comparison/src/ssr-load-process-owner.mjs';
import {startSsrWorker,stopSsrWorker,controlSsrWorker} from '../../framework-comparison/src/ssr-worker-controller.mjs';
import {availableSsrRuntimes,measureSsrArtifact,ssrEnvironmentMetadata} from '../../framework-comparison/src/ssr-run-environment.mjs';
const plan=JSON.parse(await readFile(process.argv[2],'utf8')),output=process.argv[3];
const runtimeId=process.argv[4]; if(!['node','bun'].includes(runtimeId))throw Error('Invalid runtime'); const runtimes=availableSsrRuntimes('node,bun');
const artifacts={}; const identities={};
for(const id of ['exact','react']){
 const path=resolve(`framework-comparison/participants/${id}/${runtimeId==='bun'?'dist-bun-server/bun-server-entry.js':'dist-server/server-entry.js'}`);
 const bytes=await readFile(path);artifacts[id]={path,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')};

}
artifacts.server=await measureSsrArtifact(resolve('packages/server/dist'));
artifacts[runtimeId==='bun'?'bunAdapter':'nodeAdapter']=await measureSsrArtifact(resolve(`framework-adapters/${runtimeId==='bun'?'bun':'node'}-adapter/dist`));
const prior={artifacts,environment:ssrEnvironmentMetadata(runtimes)};
const report={kind:'multi-driver-preloaded-ssr',complete:false,runtimeId,transports:{exact:runtimeId==='bun'?'bun-fetch':'node-http',react:runtimeId==='bun'?'bun-fetch':'node-http'},createdAt:new Date().toISOString(),plan,artifacts:prior.artifacts,environment:prior.environment,blocks:[],runner:await readFile(import.meta.filename,'utf8')};
const runtime=availableSsrRuntimes(runtimeId)[0];let service,worker,drivers=[],timer,polling;
async function close(){clearInterval(timer);const ds=drivers;drivers=[];const closed=await Promise.allSettled(ds.map(d=>d.close()));await polling;if(worker){const w=worker;worker=undefined;await stopSsrWorker(w);}if(service){const s=service;service=undefined;await s.close();}const failures=closed.filter(x=>x.status==='rejected');if(failures.length)throw new AggregateError(failures.map(x=>x.reason));}
async function verify(){for(const id of ['exact','react']){const a=report.artifacts[id];assert.equal(createHash('sha256').update(await readFile(a.path)).digest('hex'),a.sha256);}}
const lifecycle=installDevelopmentProcessLifecycle({label:'Multi-driver preloaded SSR',close});
try{await verify();for(let population=0;population<2;population++)for(const id of population?['react','exact']:['exact','react']){
 const serviceIntervals=[],telemetry=[],telemetryErrors=[];
 service=await startSsrLoadProcess('service',{onInterval:r=>serviceIntervals.push(r)});
 worker=await startSsrWorker({runtime,participantId:id,transport:runtimeId==='bun'?'bun-fetch':'node-http',workerPath:resolve('framework-comparison/src/ssr-benchmark-worker.mjs'),workingDirectory:resolve('framework-comparison'),serviceUrl:service.url,environment:{COMPARISON_SSR_BOUNDED_TELEMETRY:'1',...(id==='exact'?{COMPARISON_EXACT_SERVER_ENTRY:report.artifacts.exact.path}:{})}});
 const response=await fetch(worker.url+(plan.preloaded===false?'':'?__benchmarkPreloaded=true')); assert.equal(response.status,200); const body=Buffer.from(await response.arrayBuffer()); assert.ok(body.toString().includes('Delayed fulfillment events')); identities[id]={bytes:body.length,hash:createHash('sha256').update(body).digest('hex')};
 await controlSsrWorker(worker,'reset');
 telemetry.push({epochMs:Date.now(),value:await controlSsrWorker(worker,'telemetry')});
 timer=setInterval(()=>{if(polling)return;polling=controlSsrWorker(worker,'telemetry').then(value=>telemetry.push({epochMs:Date.now(),value}),e=>telemetryErrors.push(e.message)).finally(()=>{polling=undefined;});},1000);
 for(let i=0;i<plan.drivers;i++)drivers.push(await startSsrLoadProcess('driver'));
 console.log('Population',population+1,id,'drivers',drivers.length);
 for(const d of drivers)d.run({url:worker.url+(plan.preloaded===false?'':'?__benchmarkPreloaded=true'),contains:'Delayed fulfillment events',expectedIdentity:identities[id],maxInFlight:256,maxLagMs:50,timeoutMs:10000,stages:plan.stages});
 const results=await Promise.race([Promise.all(drivers.map(d=>d.result)),service.result]);
 for(const r of results)for(const s of r.stages){assert.equal(s.offered,s.started+s.missedLag+s.missedCapacity+s.missedDeadline);assert.equal(s.completed,s.valid+s.errors);assert.equal(s.started,s.completed);}
 clearInterval(timer);await polling;telemetry.push({epochMs:Date.now(),value:await controlSsrWorker(worker,'telemetry')});
 const block={population,id,workerPid:worker.child.pid,workerStderr:worker.stderr(),servicePid:service.pid,results,telemetry,telemetryErrors,serviceIntervals};report.blocks.push(block);
 for(let i=0;i<plan.stages.length;i++){const ss=results.map(r=>r.stages[i]);console.log(ss[0].name,JSON.stringify({rps:ss.reduce((n,s)=>n+s.validRps,0),errors:ss.reduce((n,s)=>n+s.errors,0),misses:ss.reduce((n,s)=>n+s.missedCapacity+s.missedLag+s.missedDeadline,0)}));}
 await close();await writeFile(output,JSON.stringify(report));
 }await verify();assert.deepEqual(await measureSsrArtifact(resolve('packages/server/dist')),artifacts.server);assert.deepEqual(await measureSsrArtifact(resolve(`framework-adapters/${runtimeId==='bun'?'bun':'node'}-adapter/dist`)),artifacts[runtimeId==='bun'?'bunAdapter':'nodeAdapter']);report.complete=true;await writeFile(output,JSON.stringify(report));
}finally{await close();lifecycle.dispose();}

runners.publish:
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, writeFile, copyFile } from 'node:fs/promises';
import { summarizePercentiles } from '../../framework-comparison/src/percentile-summary.mjs';
import { createSsrCapacityReport } from '../../framework-comparison/src/publish-ssr-capacity.mjs';
import { createHeapCompositionReport } from '../../framework-comparison/src/browser-heap-composition.mjs';
import { refreshDocsSsrDiagnostics, refreshDocsBunSsrDiagnostics } from '../../scripts/component-local-target-abi/refresh-docs-ssr-report.mjs';
import { adaptFrameworkComparisonBrowserRun, adaptFrameworkComparisonStartupCpu } from '../../scripts/component-local-target-abi/framework-comparison-adapters.mjs';

const root = '.tmp/post-audit-performance';
const prefix = 'docs/performance-baselines/post-audit-2026-09-07';
const json = async path => JSON.parse(await readFile(path, 'utf8'));
const [browser, heap, ssr, startup, previous, framework, collections] = await Promise.all(
  ['browser', 'heap', 'ssr', 'startup', 'before-performance-report', 'framework', 'collections'].map(name => json(`${root}/${name}.json`))
);
assert.equal(browser.publishable, true);
assert.equal(startup.complete, true);
assert.equal(framework.complete, true);
adaptFrameworkComparisonBrowserRun(browser);
adaptFrameworkComparisonStartupCpu(startup);
for (const entry of heap.participants) {
  const id = `${entry.id}-controlled`;
  const hash = browser.complexity.find(value => value.participantId === id).artifacts.hash;
  assert.equal(entry.artifactHash, hash);
  assert.equal(startup.artifacts[id], hash);
}
const readers = {
  'Navigation completion': sample => sample.navigation.durationMs,
  'First contentful paint': sample => sample.navigation.firstContentfulPaintMs,
  'Optimistic feedback': sample => sample.optimisticFeedbackMs,
  'Authoritative settlement': sample => sample.settlementMs,
  'Warm browser used heap': sample => sample.heapBytes / 1e6
};
const ids = { Exact: 'exact-controlled', React: 'react-controlled', SvelteKit: 'sveltekit-controlled', Nuxt: 'nuxt-controlled', 'TanStack Start': 'tanstack-start-controlled' };
const browserCharts = previous.browserCharts.map(chart => ({
  ...chart,
  series: chart.series.map(series => ({ name: series.name, stats: summarizePercentiles(browser.browser[ids[series.name]].samples.map(readers[chart.title])) }))
}));
const chartMean = title => browserCharts.find(chart => chart.title === title).series.find(series => series.name === 'Exact').stats.mean;
let report = refreshDocsBunSsrDiagnostics(refreshDocsSsrDiagnostics({
  ...previous,
  browserCharts,
  metadata: {
    ...previous.metadata,
    commit: browser.harness.commit.slice(0, 8) + (browser.harness.workingTreeDirty ? '+worktree' : ''),
    browserCreatedAt: browser.createdAt,
    browserCommit: browser.harness.commit,
    browserSamples: browser.harness.sampleCount,
    startupSamples: startup.harness.sampleCount,
    startupCreatedAt: startup.createdAt,
    browserDelivery: browser.harness.clientDelivery,
    browserEnvironment: browser.environment
  },
  summary: [
    { label: 'Optimistic mean', value: chartMean('Optimistic feedback').toFixed(2) + ' ms', context: 'visible client feedback' },
    { label: 'Warm browser heap', value: chartMean('Warm browser used heap').toFixed(2) + ' MB', context: 'post-GC used heap' }
  ]
}, ssr), ssr);
report.metadata.capture = 'post-adversarial-audit-2026-09-07';
report.metadata.createdAt = new Date().toISOString();
const sources = {};
for (const lane of ['browser', 'heap', 'ssr', 'startup', 'node-multi', 'node-normal', 'node-arrivals', 'bun-multi', 'bun-normal', 'bun-arrivals', 'collections', 'framework']) {
  const path = `${prefix}-${lane}.json`;
  await copyFile(`${root}/${lane}.json`, path);
  sources[lane] = { path, sha256: createHash('sha256').update(await readFile(path)).digest('hex') };
}
report.metadata.sources = {
  browser: sources.browser, heap: sources.heap, startupCpu: sources.startup,
  ssrDiagnostics: sources.ssr, ssrBunDiagnostics: sources.ssr
};
report.metadata.browserSource = sources.browser;
const capacities = {};
for (const runtime of ['node', 'bun']) {
  const lanes = Object.fromEntries(await Promise.all(['multi', 'normal', 'arrivals'].map(async lane => [lane, await json(`${root}/${runtime}-${lane}.json`)])));
  const capacity = createSsrCapacityReport(lanes, lanes.normal);
  capacities[runtime] = capacity;
  await writeFile(`apps/docs/src/data/ssr-${runtime === 'bun' ? 'bun-' : ''}capacity-report.json`, JSON.stringify(capacity, null, 2) + '\n');
}
await writeFile(`${root}/report-data.json`, JSON.stringify(report, null, 2) + '\n');
await writeFile('apps/docs/src/data/performance-heap-report.json', JSON.stringify(createHeapCompositionReport(heap), null, 2) + '\n');
const decodeLog = async name => {
  const bytes = await readFile(`${root}/${name}.log`);
  return bytes.toString(bytes[0] === 255 && bytes[1] === 254 ? 'utf16le' : 'utf8');
};
const reactive = JSON.parse((await decodeLog('reactive')).split('REACTIVE_BENCHMARK_JSON=')[1].trim());
const dom = JSON.parse((await decodeLog('dom-list')).split('DOM_LIST_BENCHMARK_JSON=')[1].trim());
const previousCapacity = {
  node: await json(`${root}/before-ssr-capacity-report.json`),
  bun: await json(`${root}/before-ssr-bun-capacity-report.json`)
};
const comparison = {
  browser: browserCharts.map(chart => ({ metric: chart.title, unit: chart.unit, current: chart.series[0].stats.mean, previous: previous.browserCharts.find(old => old.title === chart.title).series[0].stats.mean })),
  capacities: Object.fromEntries(['node', 'bun'].map(runtime => [runtime, capacities[runtime].preloaded.map(row => ({ ...row, previousRps: previousCapacity[runtime].preloaded.find(old => old.name === row.name && old.concurrency === row.concurrency).rps }))]))
};
const archive = {
  createdAt: report.metadata.createdAt, sources, report, capacities, comparison, reactive, dom, collections,
  framework, previousReport: previous, previousCapacity,
  environment: { browser: browser.environment, startup: startup.environment, ssr: ssr.environment },
  harness: { browser: browser.harness, startup: startup.harness, ssr: ssr.harness },
  artifactIdentities: browser.complexity.map(entry => ({ participant: entry.participantId, artifact: entry.artifacts })),
  runners: { measure: await readFile('.tmp/post-audit-measure.ps1', 'utf8'), capacity: await readFile(`${root}/capacity-runner.mjs`, 'utf8'), publish: await readFile(import.meta.filename, 'utf8') }
};
await writeFile(`${prefix}.json`, JSON.stringify(archive, null, 2) + '\n');
await writeFile(`${root}/comparison.json`, JSON.stringify(comparison, null, 2) + '\n');
console.log(JSON.stringify({ comparison, capacities }, null, 2));
